# test_slugify.py
from your_module import slugify


def test_slugify_converts_text_to_lowercase():
    assert slugify("Hello World") == "hello-world"


def test_slugify_replaces_spaces_with_hyphens():
    assert slugify("hello world again") == "hello-world-again"


def test_slugify_handles_already_lowercase_text():
    assert slugify("hello-world") == "hello-world"


def test_slugify_handles_empty_string():
    assert slugify("") == ""


def test_slugify_preserves_non_space_characters():
    assert slugify("Hello, World!") == "hello,-world!"
```

Replace `your_module` with the module containing `slugify`. These tests reflect the function’s exact behavior: it lowercases text and replaces literal spaces with hyphens, without trimming or normalizing punctuation.
